doc.h:script:
setTimeout(() => {
	const a = document.getElementById('a');
	window.__pi = {
		done: true,
		cases: {
			xml: {
				color: getComputedStyle(a).color,
				contentType: document.contentType,
				href: location.href,
				top: top === window,
				children: [...document.childNodes].map((node) => node.nodeType),
				sheets: document.styleSheets.length,
			},
		},
	};
}, 1000);
